def source_html(i):
    a,b=sections[i]
    return f'<p class="source"><strong>Fachquelle:</strong> ISTQB, <a href="{source}" target="_blank" rel="noopener">Certified Tester Foundation Level Syllabus v4.0.1</a> (15.09.2024), Abschnitt {escape(a)}. {escape(b)}.</p>'
def paragraphs(s):return ''.join('<p>'+escape(x)+'</p>' for x in s.split('\n\n'))
def slide_html(i,sl):
    label,title,layout,body=sl
    return f'<section class="slide {layout}" id="folie-{i+1}" aria-labelledby="titel-{i+1}"><h2 id="titel-{i+1}" tabindex="-1">{title}</h2>{body}</section>'
slide_markup='\n'.join(slide_html(i,sl) for i,sl in enumerate(slides))
appendix=''.join(f'<section class="read-entry"><h3>{i+1}. {sl[1]}</h3>{paragraphs(notes[i])}{source_html(i)}</section>' for i,sl in enumerate(slides))
